class HybridGAandLocalSearch:
    def __init__(self, budget=10000, dim=10, population_size=20, mutation_rate=0.1, local_search_iters=5):
        self.budget = budget
        self.dim = dim
        self.population_size = population_size
        self.mutation_rate = mutation_rate
        self.local_search_iters = local_search_iters
        self.lb = -5.0
        self.ub = 5.0
        self.evaluations = 0 # Track function evaluations

    def initialize_population(self):
        return np.random.uniform(self.lb, self.ub, size=(self.population_size, self.dim))

    def evaluate_population(self, population, func):
        fitness = np.zeros(self.population_size)
        for i, individual in enumerate(population):
            if self.evaluations < self.budget:
                fitness[i] = func(individual)
                self.evaluations += 1
            else:
                fitness[i] = np.inf # Penalize if we are out of budget
        return fitness

    def select_parents(self, population, fitness, num_parents=None):
        if num_parents is None:
            num_parents = self.population_size // 2  # Select half of the population
        # Tournament selection
        parents = []
        for _ in range(num_parents):
            tournament_size = 3  # Adjust tournament size as needed
            indices = np.random.choice(len(population), tournament_size, replace=False)
            best_index = indices[np.argmin(fitness[indices])]
            parents.append(population[best_index])
        return np.array(parents)


    def crossover(self, parents):
        offspring = []
        for i in range(0, len(parents), 2):
            if i + 1 < len(parents):
                # Two-point crossover
                point1 = np.random.randint(1, self.dim)
                point2 = np.random.randint(1, self.dim)
                if point1 > point2:
                    point1, point2 = point2, point1
                offspring1 = np.concatenate((parents[i][:point1], parents[i+1][point1:point2], parents[i][point2:]))
                offspring2 = np.concatenate((parents[i+1][:point1], parents[i][point1:point2], parents[i+1][point2:]))
                offspring.extend([offspring1, offspring2])
            else:
                offspring.append(parents[i]) # If odd number of parents, keep last parent.

        return np.array(offspring)

    def mutate(self, offspring):
        for i in range(len(offspring)):
            if np.random.rand() < self.mutation_rate:
                mutation_indices = np.random.choice(self.dim, size=int(self.dim * 0.1), replace=False) # Mutate a fraction of the genes
                offspring[i][mutation_indices] = np.random.uniform(self.lb, self.ub, size=len(mutation_indices))

        return offspring

    def local_search(self, individual, func):
        if self.evaluations >= self.budget:
            return individual, np.inf

        def local_func(x):
            nonlocal self
            if self.evaluations < self.budget:
                self.evaluations += 1
                return func(x)
            else:
                return np.inf

        result = minimize(local_func, individual, method='L-BFGS-B', bounds=[(self.lb, self.ub)] * self.dim, options={'maxiter': self.local_search_iters}) # changed to L-BFGS-B
        return result.x, result.fun



    def __call__(self, func):
        population = self.initialize_population()
        best_solution = None
        best_fitness = np.inf


        for generation in range(500): #Added an early stopping criteria to prevent running infinitely if the budget is large.
            if self.evaluations >= self.budget:
                break
            fitness = self.evaluate_population(population, func)

            for i in range(self.population_size):
                if fitness[i] < best_fitness:
                    best_fitness = fitness[i]
                    best_solution = population[i]

            parents = self.select_parents(population, fitness)
            offspring = self.crossover(parents)
            offspring = self.mutate(offspring)

            # Local search - apply to the best individuals (or all offspring)
            for i in range(len(offspring)):
                if np.random.rand() < 0.2:  # Apply local search to a fraction of the offspring
                    offspring[i], offspring_fitness = self.local_search(offspring[i], func)
                    if offspring_fitness < best_fitness:
                        best_fitness = offspring_fitness
                        best_solution = offspring[i]


            population = np.concatenate((parents, offspring)) #Combine parents and offspring to the new population
            population = population[:self.population_size] # Keep the population size constant

            if self.evaluations >= self.budget:
                break


        # Run local search on the best solution found during the GA run
        if best_solution is not None:
            best_solution, best_fitness = self.local_search(best_solution, func)


        return best_fitness, best_solution

