    def __init__(self, budget=10000, dim=10, initial_radius=1.0, radius_reduction_factor=0.8, radius_expansion_factor=1.2, local_search_iters=5):
        self.budget = budget
        self.dim = dim
        self.initial_radius = initial_radius
        self.radius_reduction_factor = radius_reduction_factor
        self.radius_expansion_factor = radius_expansion_factor
        self.local_search_iters = local_search_iters
        self.lb = -5.0
        self.ub = 5.0
        self.evaluations = 0
        self.search_radius = self.initial_radius

    def random_point(self):
        return np.random.uniform(self.lb, self.ub, size=self.dim)

    def evaluate(self, point, func):
        if self.evaluations < self.budget:
            self.evaluations += 1
            return func(point)
        else:
            return np.inf

    def local_search(self, center, func):
        if self.evaluations >= self.budget:
            return center, np.inf

        def local_func(x):
            nonlocal self
            if self.evaluations < self.budget:
                self.evaluations += 1
                return func(x)
            else:
                return np.inf

        result = minimize(local_func, center, method='L-BFGS-B', bounds=[(self.lb, self.ub)] * self.dim, options={'maxiter': self.local_search_iters}) # changed to L-BFGS-B
        return result.x, result.fun



    def __call__(self, func):
        best_solution = self.random_point()
        best_fitness = self.evaluate(best_solution, func)
        successful_local_search = False


        for _ in range(100):  # Reduced iterations and uses budget
            if self.evaluations >= self.budget:
                break


            # Random Exploration
            exploration_point = best_solution + np.random.uniform(-self.search_radius, self.search_radius, size=self.dim)
            exploration_point = np.clip(exploration_point, self.lb, self.ub)
            exploration_fitness = self.evaluate(exploration_point, func)

            if exploration_fitness < best_fitness:
                best_solution = exploration_point
                best_fitness = exploration_fitness
                successful_local_search = False #Reset the local search success flag

            # Local Search
            local_search_start = best_solution.copy() #Ensure the local search starts from a good point.
            local_search_result, local_search_fitness = self.local_search(local_search_start, func)

            if local_search_fitness < best_fitness:
                best_solution = local_search_result
                best_fitness = local_search_fitness
                successful_local_search = True
                self.search_radius *= self.radius_expansion_factor # Expand search if local search helps

            else:
                successful_local_search = False
                self.search_radius *= self.radius_reduction_factor  # Reduce search radius if local search fails

            self.search_radius = np.clip(self.search_radius, 1e-6, 5.0) #Keep search radius within reasonable bounds.

        return best_fitness, best_solution

