class GridLocalAdaptiveSearch:
    def __init__(self, budget=10000, dim=10, grid_divisions=5, local_search_iters=5, random_search_rate=0.2):
        self.budget = budget
        self.dim = dim
        self.grid_divisions = grid_divisions
        self.local_search_iters = local_search_iters
        self.random_search_rate = random_search_rate
        self.lb = -5.0
        self.ub = 5.0
        self.f_opt = np.inf
        self.x_opt = None
        self.evaluations_used = 0
        self.grid_points = None

    def _generate_grid(self):
        """Generates a grid of points within the search space."""
        grid_coords = [np.linspace(self.lb, self.ub, self.grid_divisions) for _ in range(self.dim)]
        return np.array(np.meshgrid(*grid_coords)).T.reshape(-1, self.dim)


    def _evaluate_individual(self, func, individual):
        if self.evaluations_used < self.budget:
            self.evaluations_used += 1
            return func(individual)
        else:
            return np.inf  # Return a high value if budget is exhausted


    def _local_search(self, func, individual):
        try:
            result = minimize(lambda x: func(x), individual, method='L-BFGS-B', bounds=[(self.lb, self.ub)] * self.dim,
                              options={'maxiter': self.local_search_iters})
            if result.success:
                return result.fun, result.x
            else:
                return np.inf, individual  # Return original if local search fails
        except Exception as e:
            #print(f"Local search failed: {e}")
            return np.inf, individual


    def __call__(self, func):
        # Grid Search Initialization
        self.grid_points = self._generate_grid()
        grid_fitnesses = []
        for point in self.grid_points:
            fitness = self._evaluate_individual(func, point)
            grid_fitnesses.append(fitness)
            if fitness < self.f_opt:
                self.f_opt = fitness
                self.x_opt = point

        # Adaptive Search Loop
        while self.evaluations_used < self.budget:
            # Random Search Exploration
            if np.random.rand() < self.random_search_rate:
                random_individual = np.random.uniform(self.lb, self.ub, self.dim)
                random_fitness = self._evaluate_individual(func, random_individual)
                if random_fitness < self.f_opt:
                    self.f_opt = random_fitness
                    self.x_opt = random_individual
            else:
                # Local Refinement around Grid Points (or best found)
                if np.random.rand() < 0.8 or self.x_opt is None: # Explore the best solution found, or start from a good grid point
                     start_point = self.x_opt if self.x_opt is not None else self.grid_points[np.argmin(grid_fitnesses)] #Start from global best found or best grid point
                else: # Otherwise sample a random point from the grid.
                    start_point = self.grid_points[np.random.randint(0,len(self.grid_points))]

                local_search_fitness, local_search_x = self._local_search(func, start_point)
                if local_search_fitness < self.f_opt:
                    self.f_opt = local_search_fitness
                    self.x_opt = local_search_x

        return self.f_opt, self.x_opt

