class PopulationBasedAdaptiveSearch:
    def __init__(self, budget=10000, dim=10, population_size=20, local_search_iters=5, exploration_rate=0.3, restart_threshold=0.1):
        self.budget = budget
        self.dim = dim
        self.population_size = population_size
        self.local_search_iters = local_search_iters
        self.exploration_rate = exploration_rate
        self.restart_threshold = restart_threshold
        self.lb = -5.0
        self.ub = 5.0
        self.f_opt = np.inf
        self.x_opt = None
        self.evaluations_used = 0
        self.restart_counter = 0


    def _generate_random_individual(self):
        return np.random.uniform(self.lb, self.ub, self.dim)

    def _evaluate_individual(self, func, individual):
        if self.evaluations_used < self.budget:
            self.evaluations_used += 1
            return func(individual)
        else:
            return np.inf  # Return a high value if budget is exhausted

    def _local_search(self, func, individual):
        try:
            result = minimize(lambda x: func(x), individual, method='L-BFGS-B', bounds=[(self.lb, self.ub)] * self.dim,
                              options={'maxiter': self.local_search_iters})
            if result.success:
                return result.fun, result.x
            else:
                return np.inf, individual  # Return original if local search fails
        except Exception as e:
            #print(f"Local search failed: {e}")
            return np.inf, individual

    def _population_diversity(self, population):
        if len(population) < 2:
            return 1.0  # High diversity if population is small
        distances = []
        for i in range(len(population)):
            for j in range(i + 1, len(population)):
                distances.append(np.linalg.norm(np.array(population[i]) - np.array(population[j])))
        return np.std(distances) / (np.max(distances) + 1e-9) if np.max(distances) > 0 else 0.0 # Standard deviation of pairwise distances.

    def __call__(self, func):
        # Initialize Population
        population = [self._generate_random_individual() for _ in range(self.population_size)]
        fitnesses = [self._evaluate_individual(func, individual) for individual in population]

        # Update best solution found
        for i, fitness in enumerate(fitnesses):
            if fitness < self.f_opt:
                self.f_opt = fitness
                self.x_opt = population[i]

        while self.evaluations_used < self.budget:
            # Adaptive Exploration and Exploitation
            if np.random.rand() < self.exploration_rate:
                # Exploration: Generate a new random individual
                new_individual = self._generate_random_individual()
                new_fitness = self._evaluate_individual(func, new_individual)
                if new_fitness < self.f_opt:
                    self.f_opt = new_fitness
                    self.x_opt = new_individual
                # Replace a random individual in the population.  This promotes diversity.
                replace_index = np.random.randint(0, self.population_size)
                population[replace_index] = new_individual
                fitnesses[replace_index] = new_fitness

            else:
                # Exploitation: Local search around the best individuals in population
                best_indices = np.argsort(fitnesses)[:int(self.population_size * 0.4)]  # Focus on the best individuals
                for index in best_indices:
                    local_search_fitness, local_search_x = self._local_search(func, population[index]) # perform local search.
                    if local_search_fitness < self.f_opt:
                        self.f_opt = local_search_fitness
                        self.x_opt = local_search_x

                    # Replace the original individual if local search improved the solution
                    if local_search_fitness < fitnesses[index]:
                        population[index] = local_search_x
                        fitnesses[index] = local_search_fitness
            # Restart Mechanism
            diversity = self._population_diversity(population)
            if self.f_opt != np.inf and diversity < self.restart_threshold:
                 self.restart_counter +=1
                 # If the population has converged too much, restart with new random individuals.
                 if self.restart_counter > 2: # Reduce restarts to save the budget
                    population = [self._generate_random_individual() for _ in range(self.population_size)]
                    fitnesses = [self._evaluate_individual(func, individual) for individual in population]
                    self.restart_counter = 0

        return self.f_opt, self.x_opt

import numpy as np

class QEA:
    def __init__(self, budget=10000, dim=10, population_size=20, q_mutation_rate=0.1,  exploration_rate = 0.8):
        self.budget = budget
        self.dim = dim
        self.population_size = population_size
        self.q_mutation_rate = q_mutation_rate
        self.exploration_rate = exploration_rate
        self.bounds = np.array([[-5.0] * self.dim, [5.0] * self.dim]).T
        self.remaining_budget = self.budget
        self.best_solution = None
        self.best_fitness = np.inf


    def initialize_qubits(self):
        # Qubit representation: Each qubit represents a position in the search space,
        # with a probability amplitude for being 0 or 1 (mapped to bounds).
        return np.random.rand(self.population_size, self.dim, 2)  # [population, dimension, probability amplitudes for 0 and 1]

    def measure_qubits(self, qubits):
        # Collapse the superposition (qubits) to a definite state (position in search space).
        population = np.zeros((self.population_size, self.dim))
        for i in range(self.population_size):
            for j in range(self.dim):
                if np.random.rand() < qubits[i, j, 0]**2:  # Probability of 0 state
                    population[i, j] = self.bounds[j, 0]  # Map 0 to lower bound
                else:
                    population[i, j] = self.bounds[j, 1]  # Map 1 to upper bound
        return population

    def evaluate_population(self, func, population):
        fitness = np.zeros(len(population))
        for i in range(len(population)):
            if self.remaining_budget <= 0:
                break
            fitness[i] = func(population[i])
            self.remaining_budget -= 1
        return fitness


    def quantum_rotation_gate(self, qubit, delta):
        # Rotate the qubit's probability amplitudes.  delta is a function of the solution quality.
        theta = delta  # Simplified: delta directly controls the rotation angle
        new_qubit = np.zeros_like(qubit)
        new_qubit[0] = np.cos(theta) * qubit[0] - np.sin(theta) * qubit[1]  # Apply rotation matrix
        new_qubit[1] = np.sin(theta) * qubit[0] + np.cos(theta) * qubit[1]
        return new_qubit

    def update_qubits(self, qubits, population, fitness, best_solution, best_fitness):

        for i in range(self.population_size):
            for j in range(self.dim):
                # Calculate delta based on the difference between the current solution and the best solution
                if fitness[i] < best_fitness:
                    delta = self.exploration_rate * (best_solution[j] - population[i, j]) / (self.bounds[j, 1] - self.bounds[j, 0])
                else:
                    delta = -self.exploration_rate * (best_solution[j] - population[i, j]) / (self.bounds[j, 1] - self.bounds[j, 0])
                qubits[i, j] = self.quantum_rotation_gate(qubits[i, j], delta)


    def mutate_qubits(self, qubits):
        mutation_mask = np.random.rand(*qubits.shape[:2]) < self.q_mutation_rate
        for i in range(self.population_size):
            for j in range(self.dim):
                if mutation_mask[i, j]:
                    # Randomly change the qubit's state (flip probabilities)
                    qubits[i, j] = np.random.rand(2) / np.sum(np.random.rand(2))  # Normalize for probabilities

    def __call__(self, func):
        qubits = self.initialize_qubits()

        for i in range(100): #Added iterations, use budget more efficiently
            if self.remaining_budget <= 0:
