            population = self.measure_qubits(qubits)
            fitness = self.evaluate_population(func, population)

            best_index = np.argmin(fitness)
            if fitness[best_index] < self.best_fitness:
                self.best_fitness = fitness[best_index]
                self.best_solution = population[best_index].copy()

            self.update_qubits(qubits, population, fitness, self.best_solution, self.best_fitness)
            self.mutate_qubits(qubits)

            # Adaptive Mutation
