import numpy as np

class AdaptiveDifferentialEvolutionLocalSearch:
    def __init__(self, budget=10000, dim=10, population_size=20, mutation_factor=0.5, crossover_probability=0.9, local_search_steps=10,  adaptive_parameters = True):
        self.budget = budget
        self.dim = dim
        self.population_size = population_size
        self.mutation_factor = mutation_factor
        self.crossover_probability = crossover_probability
        self.local_search_steps = local_search_steps
        self.bounds = np.array([[-5.0] * self.dim, [5.0] * self.dim]).T
        self.remaining_budget = self.budget
        self.best_solution = None
        self.best_fitness = np.inf
        self.adaptive_parameters = adaptive_parameters

    def initialize_population(self):
        return np.random.uniform(self.bounds[:, 0], self.bounds[:, 1], size=(self.population_size, self.dim))

    def evaluate_population(self, func, population):
        fitness = np.zeros(len(population))
        for i in range(len(population)):
            if self.remaining_budget <= 0:
                break
            fitness[i] = func(population[i])
            self.remaining_budget -= 1
        return fitness

    def mutate(self, population, mutation_factor):
        mutated_population = np.zeros_like(population)
        for i in range(len(population)):
            indices = np.random.choice(len(population), 3, replace=False)
            v1, v2, v3 = population[indices]
            mutated_population[i] = v1 + mutation_factor * (v2 - v3)
        return mutated_population

    def crossover(self, population, mutated_population, crossover_probability):
        offspring = np.zeros_like(population)
        for i in range(len(population)):
            for j in range(self.dim):
                if np.random.rand() < crossover_probability:
                    offspring[i, j] = mutated_population[i, j]
                else:
                    offspring[i, j] = population[i, j]
        return offspring

    def clip_to_bounds(self, individual):
        return np.clip(individual, self.bounds[:, 0], self.bounds[:, 1])

    def local_search(self, func, x):
        best_x = x.copy()
        best_f = func(x)
        self.remaining_budget -= 1
        for _ in range(self.local_search_steps):
            if self.remaining_budget <= 0:
                break
            # Generate a small perturbation
            perturbation = np.random.normal(0, 0.1, size=self.dim)
            new_x = best_x + perturbation
            # Clip to bounds
            new_x = self.clip_to_bounds(new_x)

            new_f = func(new_x)
            self.remaining_budget -= 1
            if new_f < best_f:
                best_f = new_f
                best_x = new_x
        return best_f, best_x


    def __call__(self, func):
        population = self.initialize_population()
        fitness = self.evaluate_population(func, population)

        for i in range(100): #Added iterations, use budget more efficiently
            if self.remaining_budget <= 0:
                break

            # DE steps
            mutated_population = self.mutate(population, self.mutation_factor)
            offspring = self.crossover(population, mutated_population, self.crossover_probability)
            offspring = np.array([self.clip_to_bounds(ind) for ind in offspring])  # Clip after crossover
            offspring_fitness = self.evaluate_population(func, offspring)

            # Selection
            for j in range(self.population_size):
                if offspring_fitness[j] < fitness[j]:
                    population[j] = offspring[j]
                    fitness[j] = offspring_fitness[j]


            # Adaptive Parameter Control
            if self.adaptive_parameters and i % 10 == 0:
                 #Adapt mutation factor
                if np.std(fitness) < 1e-6:
                    self.mutation_factor = min(self.mutation_factor * 1.2, 1.0) #Increase if converged
                else:
                    self.mutation_factor = max(self.mutation_factor * 0.95, 0.1) #Decrease if not converged

                 # Adapt crossover probability
                if np.std(fitness) < 1e-6:
                    self.crossover_probability = min(self.crossover_probability * 1.1, 1.0) #Increase if converged
                else:
                    self.crossover_probability = max(self.crossover_probability * 0.9, 0.0) #Decrease if not converged

            # Local Search on the best individual
            best_idx = np.argmin(fitness)
            if fitness[best_idx] < self.best_fitness:
                self.best_fitness = fitness[best_idx]
                self.best_solution = population[best_idx].copy()
                self.best_fitness, self.best_solution = self.local_search(func, self.best_solution)

        return self.best_fitness, self.best_solution
